t1 = bst_insert(t1, 5);
assert(bst_search(t1, 5));

// 右插
auto t2 = bst_insert(nullptr, 10);
t2 = bst_insert(t2, 15);
assert(bst_search(t2, 15));

// 混合插入，验证结构仍是合法 BST
auto t3 = bst_insert(nullptr, 10);
t3 = bst_insert(t3, 5);
t3 = bst_insert(t3, 15);
t3 = bst_insert(t3, 3);
t3 = bst_insert(t3, 7);
validate_bst(t3);   // 不抛异常即通过
assert(bst_search(t3, 7));
assert(!bst_search(t3, 8));
```

以后遇到“测试都过了但逻辑明显该错”的情况，优先怀疑测试覆盖不全，而不是代码侥幸正确。这次的 bug 就是典型的“单侧测试掩盖双向错误”。

